SELECT l.*, e."ANA Pattern"
FROM Laboratory l
LEFT JOIN Examination e ON l.ID = e.ID AND l.Date = e."Examination Date";

SELECT l.ID, l.Date, e.`ANA Pattern`
FROM Laboratory l
LEFT JOIN Examination e ON l.ID = e.ID;

SELECT L.ID AS Lab_ID, L.Date AS Lab_Date, E.`ANA Pattern`
FROM Laboratory L
JOIN Examination E ON L.ID = E.ID;
